<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/config/inventory_step13.php';

if (empty($_SESSION['inventory_adjust_csrf'])) $_SESSION['inventory_adjust_csrf'] = bin2hex(random_bytes(24));
$csrf=(string)$_SESSION['inventory_adjust_csrf'];$error=null;$success=null;$batches=[];$recent=[];
try{
 $pdo=business_db();inventory_step13_ensure($pdo);$ctx=inventory_step13_context($pdo);$orgId=(int)$ctx['organization_id'];$locationId=(int)$ctx['location_id'];
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');
  $batchId=(int)($_POST['batch_id']??0);$type=(string)($_POST['movement_type']??'damage');$qty=(float)($_POST['quantity']??0);$date=(string)($_POST['movement_date']??date('Y-m-d'));$reference=trim((string)($_POST['reference']??''));$notes=trim((string)($_POST['notes']??''));
  if($qty<=0)throw new RuntimeException('Quantity must be greater than zero.');
  $positive=in_array($type,['customer_return','adjustment_plus'],true);$delta=$positive?$qty:-$qty;
  $txId=inventory_step13_adjust_batch($pdo,$batchId,$delta,$date,$type,$reference,$notes);$success='Inventory adjustment #'.$txId.' posted.';
 }
 $stmt=$pdo->prepare("SELECT b.id,b.batch_code,b.current_quantity,b.expiry_date,p.product_name,p.sku FROM inventory_batches b JOIN products p ON p.id=b.product_id AND p.organization_id=b.organization_id WHERE b.organization_id=? AND b.location_id=? AND b.status='active' ORDER BY p.product_name,b.expiry_date,b.id");$stmt->execute([$orgId,$locationId]);$batches=$stmt->fetchAll();
 $stmt=$pdo->prepare("SELECT t.*,p.product_name,p.sku,b.batch_code FROM inventory_transactions t JOIN products p ON p.id=t.product_id LEFT JOIN inventory_batches b ON b.id=t.batch_id WHERE t.organization_id=? AND t.movement_type IN ('damage','loss','supplier_return','adjustment_minus','adjustment_plus','customer_return','stock_count') ORDER BY t.id DESC LIMIT 100");$stmt->execute([$orgId]);$recent=$stmt->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();}
function ia_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function ia_n(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
?>
