<div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Inventory</div><nav class="os-nav"><a href="inventory_center.php"><i class="dot"></i>Inventory Center</a><a href="inventory_inward.php"><i class="dot"></i>Stock Inward</a><a class="active" href="inventory_adjustments.php"><i class="dot"></i>Damage / Returns</a><a href="inventory_stocktake.php"><i class="dot"></i>Physical Stocktake</a><a href="inventory_settings.php"><i class="dot"></i>Reorder Settings</a><a href="inventory_analytics.php"><i class="dot"></i>Analytics</a></nav></aside>
<main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 13B • CONTROLLED STOCK MOVEMENTS</div><h1>Record damage, loss, returns and corrections without deleting inventory history.</h1><p>Every adjustment targets a specific batch and creates a signed ledger movement. Negative stock is blocked unless a future explicit policy enables it.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'ADJUSTMENT CENTER LIVE':'Review required' ?></span><span class="os-chip">No hard delete</span><span class="os-chip">Batch-specific</span></div></section>
<?php if($error):?><div class="pp-alert bad"><strong>Adjustment diagnostic:</strong> <?= ia_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Saved:</strong> <?= ia_h($success) ?></div><?php endif;?>
<?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Post Adjustment</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= ia_h($csrf) ?>"><label>Movement Type<select name="movement_type"><option value="damage">Damage / Unsellable</option><option value="loss">Loss / Missing</option><option value="supplier_return">Return to Supplier</option><option value="adjustment_minus">Negative Correction</option><option value="customer_return">Customer Return (+)</option><option value="adjustment_plus">Positive Correction (+)</option></select></label><label>Batch<select name="batch_id" required><option value="">Choose batch…</option><?php foreach($batches as $b):?><option value="<?= (int)$b['id'] ?>"><?= ia_h(($b['sku']?:'—').' • '.$b['product_name'].' • '.$b['batch_code'].' • Qty '.ia_n($b['current_quantity']).($b['expiry_date']?' • Exp '.$b['expiry_date']:'')) ?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" min="0.001" step="0.001" required></label><label>Date<input type="date" name="movement_date" value="<?= ia_h(date('Y-m-d')) ?>" required></label><label>Reference<input name="reference" maxlength="190" placeholder="Return note, damage record, approval…"></label><label>Notes<textarea name="notes" rows="3"></textarea></label><button>Post Audited Adjustment →</button></form></article><article class="os-card pp-span-7"><h2>Adjustment History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Product</th><th>Batch</th><th>Type</th><th>Delta</th><th>Reference</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?= ia_h($r['movement_date']) ?></td><td><b><?= ia_h($r['sku']) ?></b><small><?= ia_h($r['product_name']) ?></small></td><td><?= ia_h($r['batch_code']?:'—') ?></td><td><?= ia_h(strtoupper(str_replace('_',' ',$r['movement_type']))) ?></td><td><b><?= (float)$r['quantity_delta']>0?'+':'' ?><?= ia_h(ia_n($r['quantity_delta'])) ?></b></td><td><?= ia_h($r['source_reference']?:'—') ?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="6">No inventory adjustments yet.</td></tr><?php endif;?></tbody></table></div></article></section><?php endif;?>
<div class="os-footer-note"><strong>Safety:</strong> damage/loss/supplier-return never rewrites the original inward record. It adds a new negative movement so the complete stock trail remains visible.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
